import { MeshStandardNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#121218' }, { at: 1, hex: '#0b0b10' }]
  };

  const w = 6.8;
  const h = 2.0;

  // --- VERTICAL GRADIENT BACKGROUND ---
  const bgGeom = new PlaneGeometry(w, h);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2
  });

  const stop0 = vec3(new Color(colors.gradientStops[0].hex));
  const stop1 = vec3(new Color(colors.gradientStops[1].hex));
  bgMat.colorNode = mix(stop0, stop1, uv().y);

  const bgMesh = new Mesh(bgGeom, bgMat);
  group.add(bgMesh);

  // --- HAIRLINES ---
  const lineGeom = new PlaneGeometry(w, 0.006);
  const lineMat = new MeshStandardNodeMaterial({
    color: 0x23232b,
    roughness: 0.4,
    metalness: 0.8
  });

  // Top Hairline
  const topLine = new Mesh(lineGeom, lineMat);
  topLine.position.set(0, h / 2 - 0.003, 0.005);
  group.add(topLine);

  // Bottom Hairline
  const bottomLine = new Mesh(lineGeom, lineMat);
  bottomLine.position.set(0, -h / 2 + 0.35, 0.005);
  group.add(bottomLine);

  // --- CONTENT CONTAINER ---
  const content = new Group();
  content.position.set(0, 0, 0.01);
  group.add(content);

  const startX = -w / 2 + 0.3;
  const topY = h / 2 - 0.35;

  // Left Block: Wordmark + Accent Bar
  const wordmarkBox = new Group();
  wordmarkBox.position.set(startX, topY - 0.2, 0);

  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 28,
    color: colors.paper,
    align: 'left'
  });
  wordmarkBox.add(wordmarkText);

  const barGeom = new PlaneGeometry(0.3, 0.02);
  const barMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.4
  });
  const accentBar = new Mesh(barGeom, barMat);
  accentBar.position.set(0.15, -0.15, 0);
  wordmarkBox.add(accentBar);
  content.add(wordmarkBox);

  // Three Columns Def
  const columnsData = [
    {
      header: 'ATELIER',
      links: [
        { text: 'Features', route: 'hub-features' },
        { text: 'Collection', route: 'hub-collection' },
        { text: 'Pricing', route: 'hub-pricing' }
      ]
    },
    {
      header: 'COMPANY',
      links: [
        { text: 'Journal', route: 'hub-journal' },
        { text: 'Visit the Atelier', route: 'hub-home' }, // Default safety
        { text: 'Contact', route: 'hub-home' }
      ]
    },
    {
      header: 'LEGAL',
      links: [
        { text: 'Privacy', route: 'hub-home' },
        { text: 'Terms', route: 'hub-home' },
        { text: 'Warranty', route: 'hub-home' }
      ]
    }
  ];

  const colWidth = 1.2;
  const colGutter = 0.375;
  const colStartX = startX + 2.0;

  const interactives = [];

  columnsData.forEach((col, cIdx) => {
    const colGroup = new Group();
    colGroup.position.set(colStartX + cIdx * (colWidth + colGutter), topY - 0.1, 0);

    const hText = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 3
    });
    colGroup.add(hText);

    col.links.forEach((link, lIdx) => {
      const linkGroup = new Group();
      linkGroup.position.set(0, -0.22 - lIdx * 0.18, 0);

      const lText = ctx.fontAtlas.createText(link.text, {
        fontSize: 12,
        color: colors.paper,
        align: 'left'
      });
      linkGroup.add(lText);

      // Hit area for interaction
      const hitGeom = new PlaneGeometry(colWidth, 0.16);
      const hitMat = new MeshStandardNodeMaterial({
        visible: false,
        depthWrite: false
      });
      const hit = new Mesh(hitGeom, hitMat);
      hit.position.set(colWidth / 2, 0, 0);
      linkGroup.add(hit);

      // Mouse Handlers attached directly to interactive mesh unit
      const originalColor = new Color(colors.paper);
      const hoverColor = new Color(colors.accent);

      hit.userData.onPointerOver = () => {
        gsap.to(lText.position, { z: 0.02, duration: 0.14, ease: 'power1.out' });
        // Direct material property animation
        if (lText.material) {
          gsap.to(lText.material.color, {
            r: hoverColor.r,
            g: hoverColor.g,
            b: hoverColor.b,
            duration: 0.14,
            ease: 'power1.out'
          });
        }
      };

      hit.userData.onPointerOut = () => {
        gsap.to(lText.position, { z: 0.0, duration: 0.14, ease: 'power1.out' });
        if (lText.material) {
          gsap.to(lText.material.color, {
            r: originalColor.r,
            g: originalColor.g,
            b: originalColor.b,
            duration: 0.14,
            ease: 'power1.out'
          });
        }
      };

      hit.userData.onClick = () => {
        ctx.emit('navigate', { to: link.route });
      };

      interactives.push(hit);
      colGroup.add(linkGroup);
    });

    content.add(colGroup);
  });

  // --- LEGAL LINE ---
  const legalText = ctx.fontAtlas.createText('(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', {
    fontSize: 9,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1
  });
  legalText.position.set(startX, -h / 2 + 0.16, 0);
  content.add(legalText);

  // Set initial state for entrance
  group.position.y += 0.2;
  bgMat.opacity = 0;
  bgMat.transparent = true;
  content.cascadeOpacity = 0; // standard custom property setup

  // Entrance timeline
  const entranceTl = gsap.timeline();
  entranceTl.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'power2.out'
  });
  entranceTl.to(bgMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'power2.out'
  }, 0);

  // Global event delegation array
  group.userData.handlers = {
    pointerover: (e) => {
      const hit = interactives.find(i => i === e.intersection?.object);
      if (hit && hit.userData.onPointerOver) hit.userData.onPointerOver();
    },
    pointerout: (e) => {
      const hit = interactives.find(i => i === e.intersection?.object);
      if (hit && hit.userData.onPointerOut) hit.userData.onPointerOut();
    },
    click: (e) => {
      const hit = interactives.find(i => i === e.intersection?.object);
      if (hit && hit.userData.onClick) hit.userData.onClick();
    }
  };

  group.userData.cleanup = () => {
    entranceTl.kill();
    bgGeom.dispose();
    bgMat.dispose();
    lineGeom.dispose();
    lineMat.dispose();
    barGeom.dispose();
    barMat.dispose();
  };

  return group;
}
